{
  "artifact": {
    "path": "union-acceptance/readable-paths/omitted-root-traversal.test.mjs",
    "text": "import test from 'node:test';
import assert from 'node:assert';
import { mkdtempSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createAgentTools } from '../../src/agent-tools.mjs';

test('omitted-root-traversal', (t) => {
  const root = mkdtempSync(join(tmpdir(), 'test-'));
  t.after(() => rmSync(root, { recursive: true }));
  const token = 'SECRET_TOKEN_MATCH';
  mkdirSync(join(root, 'public'));
  mkdirSync(join(root, 'private'));
  writeFileSync(join(root, 'public/match.txt'), `content contains ${token}`);
  writeFileSync(join(root, 'private/secret.txt'), `private content contains ${token}`);
  const tools = createAgentTools({ root, readablePaths: ['public'] });
  const listResult = JSON.parse(tools.execute({ action: 'list_files', args: {} }));
  assert.strictEqual(listResult.error, undefined, 'List should succeed without error');
  assert.ok(listResult.files.includes('public/match.txt'), 'Public file must be listed');
  assert.ok(!listResult.files.includes('private/secret.txt'), 'Private file must not be listed');
  const searchResult = JSON.parse(tools.execute({ action: 'search', args: { query: token } }));
  assert.strictEqual(searchResult.error, undefined, 'Search should succeed without error');
  const hits = searchResult.hits || [];
  assert.strictEqual(hits.length, 1, 'Exactly one hit expected');
  assert.strictEqual(hits[0].path, 'public/match.txt', 'Hit must originate from public file');
  const serialized = JSON.stringify(searchResult);
  assert.ok(!serialized.includes('private/secret.txt'), 'Serialized response must omit private filename');
  assert.ok(!serialized.includes('private content'), 'Serialized response must omit private content');
});"
  },
  "rationale": "This test artifact validates the isolation of readablePaths when the root path is omitted. It creates a temporary directory with both public and private subdirectories, configures the agent tools with restrictive readablePaths, and asserts that both list_files and search operations are correctly confined to the public scope, ensuring private data exposure is prevented."
}

